use super::*;
use crate::{ee2_up15_attack as a,native_attack_clock as clock};
fn game(epoch:u8)->Game{let mut g=Game::new(7,0,0,2,0);for i in 0..g.high{g.kill(i);}g.territory.claims.fill(NONE);g.build_grid();g.players[0].epoch=epoch;g.players[1].epoch=epoch;g.rebuild_modifiers(0,false);g.rebuild_modifiers(1,false);g.team_vis.fill(255);g}
fn put(b:&mut[u8],at:usize,value:u32){b[at..at+4].copy_from_slice(&value.to_le_bytes());}
fn round(g:&mut Game,i:usize,t:usize){let mut e=g.ents[i];let w=DEFS[e.def as usize].w[0];g.try_attack_round(i,&mut e,&w,t);g.ents[i]=e;}
#[test]fn actual_antiaircraft_and_destroyer_acquire_aircraft(){
 for id in [25,32]{let mut g=game(10);let own=g.spawn(id,0,100.5,100.5);let target=g.spawn(37,1,105.5,100.5);g.build_grid();assert!(DEFS[id as usize].weapon_vs(AIR).is_some());assert!(g.rps_allows(&g.ents[own],&g.ents[target]));assert_eq!(g.acquire(&g.ents[own],&DEFS[id as usize],11.0),g.h(target));}
}
#[test]fn proven_rps_class_survives_lower_owner_epoch(){let mut g=game(13);g.players[1].epoch=0;let f=g.spawn(FORTRESS,0,100.5,100.5);let sub=g.spawn(34,1,103.5,100.5);g.ents[sub].reveal_t=10.0;g.build_grid();assert!(!g.rps_allows(&g.ents[f],&g.ents[sub]));assert_eq!(g.acquire(&g.ents[f],&DEFS[FORTRESS as usize],11.0),NONE);}
#[test]fn native_direct_bullet_has_no_synthetic_moving_projectile(){let mut g=game(10);let own=g.spawn(16,0,100.5,100.5);let target=g.spawn(WORKER,1,105.5,100.5);g.ents[target].hp=1000.0;assert!(!a::lookup(16,10).unwrap().missile);let mut e=g.ents[own];g.fire(&mut e,&DEFS[16].w[0],target);assert!(g.projs.is_empty());assert!(g.ents[target].hp<1000.0);}
#[test]fn named_ammo_uses_its_original_move_speed(){let mut g=game(12);let own=g.spawn(25,0,100.5,100.5);let target=g.spawn(37,1,105.5,100.5);let mut e=g.ents[own];g.fire(&mut e,&DEFS[25].w[0],target);let shot=g.projs.last().unwrap();assert_eq!(shot.speed,11.0);assert_eq!(shot.splash,0.0);assert_eq!(shot.kind,W_MISSILE);}
#[test]fn artillery_minimum_range_rejects_close_targets(){let mut g=game(5);let own=g.spawn(20,0,100.5,100.5);let target=g.spawn(WORKER,1,102.5,100.5);g.build_grid();assert_eq!(g.native_attack_min(&g.ents[own],&g.ents[target]),4.0);assert_eq!(g.acquire(&g.ents[own],&DEFS[20],12.0),NONE);g.ents[target].x=106.5;g.build_grid();assert_eq!(g.acquire(&g.ents[own],&DEFS[20],12.0),g.h(target));}
#[test]fn native_friendly_fraction_and_bomber_radius_binder(){assert_eq!(a::lookup(20,1).unwrap().splash,1.0);assert_eq!(a::lookup(20,1).unwrap().friendly,0.0);assert_eq!(a::lookup(38,14).unwrap().splash,3.0);assert_eq!(a::min_range(a::lookup(38,14).unwrap(),true),0.0);}
#[test]fn source_round_waits_for_damage_time(){let mut g=game(0);let own=g.spawn(9,0,100.5,100.5);let target=g.spawn(WORKER,1,101.5,100.5);g.ents[target].hp=1000.0;g.tick=0;round(&mut g,own,target);assert_eq!(g.ents[target].hp,1000.0);for tick in 1..=8{g.tick=tick;round(&mut g,own,target);assert_eq!(g.ents[target].hp,1000.0);}for tick in 9..=13{g.tick=tick;round(&mut g,own,target);}assert!(g.ents[target].hp<1000.0);}
#[test]fn mid_windup_roundtrip_preserves_exact_attack_clock(){let mut g=game(0);let own=g.spawn(9,0,100.5,100.5);let target=g.spawn(WORKER,1,101.5,100.5);g.ents[target].hp=1000.0;g.tick=100;round(&mut g,own,target);g.save();let bytes=g.savebuf.clone();let mut loaded=Game::load(&bytes).unwrap();assert_eq!(g.state_hash(),loaded.state_hash());assert_eq!(g.attack_clock[own].flags,loaded.attack_clock[own].flags);assert_eq!(g.attack_clock[own].next.to_bits(),loaded.attack_clock[own].next.to_bits());for tick in 101..=114{g.tick=tick;loaded.tick=tick;round(&mut g,own,target);round(&mut loaded,own,target);assert_eq!(g.ents[target].hp.to_bits(),loaded.ents[target].hp.to_bits());assert_eq!(g.state_hash(),loaded.state_hash());}}
#[cfg(not(feature="ee2-roster6"))]
#[test]fn legacy_up_cooldown_migrates_without_early_refire(){let mut g=game(0);let own=g.spawn(9,0,100.5,100.5);g.tick=200;g.ents[own].cd=2.0;g.save();let legacy=clock::split_save(&g.savebuf).unwrap().0;let loaded=Game::load(legacy).unwrap();assert_eq!(loaded.attack_clock[own].next,12.0);assert_eq!(loaded.attack_clock[own].flags,clock::INIT);}
#[test]fn malformed_attack_tail_cannot_replace_world(){let mut g=game(0);let own=g.spawn(9,0,100.5,100.5);let target=g.spawn(WORKER,1,101.5,100.5);round(&mut g,own,target);g.save();let valid=g.savebuf.clone();let size=u32::from_le_bytes(valid[valid.len()-8..valid.len()-4].try_into().unwrap())as usize;let start=valid.len()-size;let before=g.state_hash();let mut cases=Vec::new();for(at,value)in[(start,0),(start+4,2),(start+8,MAXE as u32+1),(start+12,NONE),(start+12,g.h(own)^0x10000),(start+16,f32::NAN.to_bits()),(start+16,f32::INFINITY.to_bits()),(start+16,(-1.0f32).to_bits()),(start+20,0),(start+20,0xff),(start+20,(clock::INIT|clock::STARTED)as u32),(valid.len()-8,19),(valid.len()-4,0)]{let mut b=valid.clone();put(&mut b,at,value);cases.push(b);}for n in 1..size{cases.push(valid[..valid.len()-n].to_vec());}let mut b=valid.clone();b.push(0);cases.push(b);for b in cases{assert!(Game::load(&b).is_none());assert_eq!(g.state_hash(),before);}g.save();assert_eq!(g.savebuf,valid);}
#[test]fn attack_clock_dies_with_full_generation_handle(){let mut g=game(0);let own=g.spawn(9,0,100.5,100.5);let old=g.h(own);g.attack_clock[own]=clock::Clock{handle:old,next:1000.0,flags:clock::INIT};g.kill(own);assert_eq!(g.attack_clock[own].handle,NONE);assert_eq!(g.spawn(9,0,100.5,100.5),own);assert_ne!(g.h(own),old);assert_eq!(g.attack_clock[own].handle,NONE);}
